import 'package:flutter/material.dart';

import '../../../../core/theme/app_colors.dart';
import '../models/graph_node.dart';
import '../services/graph_ai_service.dart';

/// NotebookLM-style side panel shown when any node is clicked.
/// Built with the application's navy/blue theme (#102743 panel background).
/// Displays:
/// - Title & Hierarchy breadcrumbs
/// - Student Notes from Firestore
/// - AI-enhanced explanations, Key Concepts, Examples, Quick Revision
/// - Action shortcuts: Quiz, Flashcards, AI Expand
/// - "Generated by AI · Temporary" banner
class GraphDetailPanel extends StatefulWidget {
  final GraphNode node;
  final GraphAiService aiService;
  final VoidCallback onClose;
  final String? subjectName;
  final String? topicName;
  final VoidCallback? onAiExpand;
  final void Function(String route, String nodeId)? onNavigateTool;

  const GraphDetailPanel({
    required this.node,
    required this.aiService,
    required this.onClose,
    super.key,
    this.subjectName,
    this.topicName,
    this.onAiExpand,
    this.onNavigateTool,
  });

  @override
  State<GraphDetailPanel> createState() => _GraphDetailPanelState();
}

class _GraphDetailPanelState extends State<GraphDetailPanel> {
  NodeExplanation? _explanation;
  bool _loading = false;
  String? _error;
  int _selectedTab = 0;

  // Tabs tailored to study workflow
  static const _tabs = [
    'Notes',
    'AI Explanation',
    'Key Concepts',
    'Examples',
    'Quick Revision',
  ];

  static const Color _panelBg = Color(0xFF102743);
  static const Color _panelBorder = Color(0xFF1E3A5F);

  @override
  void initState() {
    super.initState();
    // Default to 'Notes' if node has notes, else 'AI Explanation'
    _selectedTab = widget.node.notes.isNotEmpty ? 0 : 1;
    _loadExplanation();
  }

  @override
  void didUpdateWidget(GraphDetailPanel old) {
    super.didUpdateWidget(old);
    if (old.node.id != widget.node.id) {
      _explanation = null;
      _selectedTab = widget.node.notes.isNotEmpty ? 0 : 1;
      _loadExplanation();
    }
  }

  Future<void> _loadExplanation() async {
    if (widget.node.type == GraphNodeType.subject) return;
    setState(() {
      _loading = true;
      _error = null;
    });

    try {
      // Pass student's actual Firestore notes if present
      final notesText = widget.node.notes.isNotEmpty
          ? widget.node.notes
              .map((n) => '${n['title'] ?? 'Note'}: ${n['content'] ?? ''}')
              .join('\n\n')
          : null;

      final explanation = await widget.aiService.explainNode(
        nodeLabel: widget.node.label,
        nodeType: widget.node.type,
        notes: notesText,
        subjectName: widget.subjectName,
        topicName: widget.topicName,
      );
      if (mounted) setState(() => _explanation = explanation);
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final isDesktop = MediaQuery.of(context).size.width > 900;
    if (isDesktop) {
      return _buildDesktopPanel();
    }
    return _buildMobileSheet();
  }

  Widget _buildDesktopPanel() {
    return Container(
      width: 400,
      height: double.infinity,
      decoration: const BoxDecoration(
        color: _panelBg,
        border: Border(
          left: BorderSide(color: _panelBorder, width: 1.2),
        ),
        boxShadow: [
          BoxShadow(
            color: Color(0x33000000),
            blurRadius: 20,
            offset: Offset(-4, 0),
          ),
        ],
      ),
      child: _panelContent(),
    );
  }

  Widget _buildMobileSheet() {
    return Container(
      constraints: BoxConstraints(
        maxHeight: MediaQuery.of(context).size.height * 0.78,
      ),
      decoration: BoxDecoration(
        color: _panelBg,
        borderRadius: const BorderRadius.vertical(top: Radius.circular(24)),
        border: Border.all(color: _panelBorder, width: 1.2),
        boxShadow: const [
          BoxShadow(
            color: Color(0x40000000),
            blurRadius: 24,
            offset: Offset(0, -6),
          ),
        ],
      ),
      child: _panelContent(),
    );
  }

  Widget _panelContent() {
    final node = widget.node;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // ── Header: Node Badge, Title, Hierarchy, Close ───────────────────────
        Container(
          padding: const EdgeInsets.fromLTRB(18, 16, 12, 14),
          decoration: const BoxDecoration(
            border: Border(bottom: BorderSide(color: _panelBorder)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  _nodeTypeBadge(node.type),
                  const Spacer(),
                  IconButton(
                    onPressed: widget.onClose,
                    icon: const Icon(
                      Icons.close_rounded,
                      color: Color(0xFF94A3B8),
                      size: 20,
                    ),
                    style: IconButton.styleFrom(
                      minimumSize: const Size(32, 32),
                      padding: EdgeInsets.zero,
                    ),
                    tooltip: 'Close panel',
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Text(
                node.label,
                style: const TextStyle(
                  fontFamily: 'Inter',
                  fontSize: 18,
                  fontWeight: FontWeight.w700,
                  letterSpacing: -0.4,
                  color: Colors.white,
                ),
              ),
              // Hierarchy Breadcrumb
              Padding(
                padding: const EdgeInsets.only(top: 4),
                child: Row(
                  children: [
                    const Icon(Icons.account_tree_outlined,
                        size: 13, color: Color(0xFF64748B)),
                    const SizedBox(width: 6),
                    Expanded(
                      child: Text(
                        _breadcrumb(),
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          fontFamily: 'Inter',
                          fontSize: 11.5,
                          color: Color(0xFF94A3B8),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),

        // ── Action Buttons ───────────────────────────────────────────────────
        if (node.type != GraphNodeType.subject)
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 12, 14, 0),
            child: _quickActions(),
          ),

        // ── Tab Bar ───────────────────────────────────────────────────────────
        if (node.type != GraphNodeType.subject)
          Container(
            margin: const EdgeInsets.fromLTRB(14, 12, 14, 0),
            height: 34,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              itemCount: _tabs.length,
              separatorBuilder: (_, __) => const SizedBox(width: 6),
              itemBuilder: (context, i) => _tabChip(i),
            ),
          ),

        // ── Content Area ───────────────────────────────────────────────────────
        Expanded(
          child: SingleChildScrollView(
            padding: const EdgeInsets.all(16),
            child: _tabContent(),
          ),
        ),
      ],
    );
  }

  Widget _quickActions() {
    final node = widget.node;
    final nodeId = node.topicId ?? node.id;

    return Row(
      children: [
        Expanded(
          child: _ActionBtn(
            icon: Icons.style_rounded,
            label: 'Flashcards',
            color: const Color(0xFF38BDF8),
            onTap: () => widget.onNavigateTool?.call('flashcards', nodeId),
          ),
        ),
        const SizedBox(width: 6),
        Expanded(
          child: _ActionBtn(
            icon: Icons.quiz_rounded,
            label: 'Quiz',
            color: const Color(0xFF34D399),
            onTap: () => widget.onNavigateTool?.call('quiz', nodeId),
          ),
        ),
        const SizedBox(width: 6),
        Expanded(
          child: _ActionBtn(
            icon: Icons.auto_awesome_rounded,
            label: 'Expand AI',
            color: const Color(0xFF2DD4BF),
            onTap: widget.onAiExpand,
          ),
        ),
      ],
    );
  }

  Widget _tabChip(int index) {
    final selected = _selectedTab == index;
    final hasBadge = index == 0 && widget.node.notes.isNotEmpty;

    return GestureDetector(
      onTap: () => setState(() => _selectedTab = index),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        decoration: BoxDecoration(
          color: selected
              ? const Color(0xFF2563EB)
              : const Color(0xFF1E3A5F).withOpacity(0.45),
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: selected
                ? const Color(0xFF3B82F6)
                : const Color(0xFF1E3A5F),
          ),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              _tabs[index],
              style: TextStyle(
                fontFamily: 'Inter',
                fontSize: 11.5,
                fontWeight: selected ? FontWeight.w700 : FontWeight.w500,
                color: selected ? Colors.white : const Color(0xFFCBD5E1),
              ),
            ),
            if (hasBadge) ...[
              const SizedBox(width: 5),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 1),
                decoration: BoxDecoration(
                  color: const Color(0xFF0284C7),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Text(
                  '${widget.node.notes.length}',
                  style: const TextStyle(
                    fontFamily: 'Inter',
                    fontSize: 9.5,
                    fontWeight: FontWeight.w700,
                    color: Colors.white,
                  ),
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  Widget _tabContent() {
    final node = widget.node;

    // Subject node
    if (node.type == GraphNodeType.subject) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _SectionBox(
            title: 'Knowledge Root',
            icon: Icons.hub_rounded,
            content:
                'You are viewing the root of "${node.label}".\n\n'
                '• Click any Topic or Subtopic to read study notes and AI explanations.\n'
                '• Click "Expand AI" on any node to generate child concept branches.\n'
                '• Use the search bar to locate specific topics and jump camera directly to them.',
          ),
        ],
      );
    }

    // Tab 0: Student Notes
    if (_selectedTab == 0) {
      return _buildStudentNotesSection();
    }

    // For AI tabs: check loading/error
    if (_loading) {
      return const _AiLoadingView();
    }
    if (_error != null) {
      return _AiErrorView(error: _error!, onRetry: _loadExplanation);
    }
    if (_explanation == null) {
      return const Center(child: Text('No explanation available.', style: TextStyle(color: Colors.white70)));
    }

    final exp = _explanation!;

    return switch (_selectedTab) {
      1 => Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _aiDisclaimerBanner(),
            const SizedBox(height: 12),
            _SectionBox(
              title: 'Overview',
              icon: Icons.info_outline_rounded,
              content: exp.overview.isNotEmpty ? exp.overview : 'No overview available.',
            ),
            const SizedBox(height: 12),
            _SectionBox(
              title: 'Detailed Explanation',
              icon: Icons.menu_book_rounded,
              content: exp.detailedExplanation.isNotEmpty ? exp.detailedExplanation : 'No detailed explanation available.',
            ),
          ],
        ),
      2 => Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _aiDisclaimerBanner(),
            const SizedBox(height: 12),
            _SectionBox(
              title: 'Key Concepts',
              icon: Icons.lightbulb_outline_rounded,
              content: exp.keyConcepts.isNotEmpty ? exp.keyConcepts : 'No key concepts available.',
            ),
            if (exp.formulas.isNotEmpty) ...[
              const SizedBox(height: 12),
              _SectionBox(
                title: 'Key Formulas & Rules',
                icon: Icons.functions_rounded,
                content: exp.formulas,
                isCode: true,
              ),
            ],
          ],
        ),
      3 => Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _aiDisclaimerBanner(),
            const SizedBox(height: 12),
            _SectionBox(
              title: 'Practical Examples',
              icon: Icons.psychology_alt_outlined,
              content: exp.examples.isNotEmpty ? exp.examples : 'No examples generated yet.',
            ),
          ],
        ),
      4 => Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _aiDisclaimerBanner(),
            const SizedBox(height: 12),
            _SectionBox(
              title: 'Summary',
              icon: Icons.summarize_outlined,
              content: exp.summary.isNotEmpty ? exp.summary : 'No summary available.',
            ),
            if (exp.memoryTricks.isNotEmpty) ...[
              const SizedBox(height: 12),
              _SectionBox(
                title: 'Memory Mnemonics',
                icon: Icons.tips_and_updates_outlined,
                content: exp.memoryTricks,
              ),
            ],
            if (exp.examQuestions.isNotEmpty) ...[
              const SizedBox(height: 12),
              _SectionBox(
                title: 'Likely Exam Questions',
                icon: Icons.assignment_outlined,
                content: exp.examQuestions,
              ),
            ],
          ],
        ),
      _ => const SizedBox.shrink(),
    };
  }

  Widget _buildStudentNotesSection() {
    final notes = widget.node.notes;
    if (notes.isEmpty) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 36),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Container(
                padding: const EdgeInsets.all(16),
                decoration: const BoxDecoration(
                  color: Color(0xFF1E3A5F),
                  shape: BoxShape.circle,
                ),
                child: const Icon(
                  Icons.sticky_note_2_outlined,
                  size: 32,
                  color: Color(0xFF38BDF8),
                ),
              ),
              const SizedBox(height: 14),
              const Text(
                'No Notes for This Concept',
                style: TextStyle(
                  fontFamily: 'Inter',
                  fontSize: 14,
                  fontWeight: FontWeight.w600,
                  color: Colors.white,
                ),
              ),
              const SizedBox(height: 6),
              const Text(
                'Notes added in the Library will appear here automatically.\nAI Explanation is available in the next tab.',
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontFamily: 'Inter',
                  fontSize: 12,
                  color: Color(0xFF94A3B8),
                  height: 1.4,
                ),
              ),
              const SizedBox(height: 18),
              FilledButton.icon(
                onPressed: () => setState(() => _selectedTab = 1),
                icon: const Icon(Icons.auto_awesome_rounded, size: 16),
                label: const Text('View AI Explanation'),
                style: FilledButton.styleFrom(
                  backgroundColor: const Color(0xFF2563EB),
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                ),
              ),
            ],
          ),
        ),
      );
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        for (final note in notes)
          Container(
            margin: const EdgeInsets.only(bottom: 12),
            padding: const EdgeInsets.all(14),
            decoration: BoxDecoration(
              color: const Color(0xFF183B63).withOpacity(0.60),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(
                color: const Color(0xFF2F6FDD).withOpacity(0.40),
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    const Icon(Icons.sticky_note_2_rounded,
                        size: 16, color: Color(0xFF38BDF8)),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        note['title']?.toString() ?? 'Note',
                        style: const TextStyle(
                          fontFamily: 'Inter',
                          fontSize: 13,
                          fontWeight: FontWeight.w700,
                          color: Colors.white,
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Text(
                  note['content']?.toString() ?? '',
                  style: const TextStyle(
                    fontFamily: 'Inter',
                    fontSize: 12.5,
                    height: 1.5,
                    color: Color(0xFFE2E8F0),
                  ),
                ),
              ],
            ),
          ),
      ],
    );
  }

  Widget _aiDisclaimerBanner() {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: const Color(0xFF14B8A6).withOpacity(0.12),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: const Color(0xFF14B8A6).withOpacity(0.35),
        ),
      ),
      child: const Row(
        children: [
          Icon(Icons.auto_awesome_rounded, size: 13, color: Color(0xFF2DD4BF)),
          SizedBox(width: 6),
          Expanded(
            child: Text(
              'Generated by AI · Temporary session',
              style: TextStyle(
                fontFamily: 'Inter',
                fontSize: 11,
                fontWeight: FontWeight.w600,
                color: Color(0xFF2DD4BF),
              ),
            ),
          ),
        ],
      ),
    );
  }

  String _breadcrumb() {
    final parts = [
      if (widget.subjectName != null) widget.subjectName!,
      if (widget.topicName != null && widget.topicName != widget.node.label)
        widget.topicName!,
      widget.node.label,
    ];
    return parts.join('  ›  ');
  }

  Widget _nodeTypeBadge(GraphNodeType type) {
    final (label, color) = switch (type) {
      GraphNodeType.subject => ('SUBJECT', const Color(0xFF3B82F6)),
      GraphNodeType.topic => ('TOPIC', const Color(0xFF2F6FDD)),
      GraphNodeType.subtopic => ('SUBTOPIC', const Color(0xFF38BDF8)),
      GraphNodeType.aiExpanded => ('AI EXPANSION', const Color(0xFF2DD4BF)),
    };

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
      decoration: BoxDecoration(
        color: color.withOpacity(0.15),
        borderRadius: BorderRadius.circular(6),
        border: Border.all(color: color.withOpacity(0.40)),
      ),
      child: Text(
        label,
        style: TextStyle(
          fontFamily: 'Inter',
          fontSize: 9.5,
          fontWeight: FontWeight.w700,
          color: color,
          letterSpacing: 0.5,
        ),
      ),
    );
  }
}

class _ActionBtn extends StatelessWidget {
  final IconData icon;
  final String label;
  final Color color;
  final VoidCallback? onTap;

  const _ActionBtn({
    required this.icon,
    required this.label,
    required this.color,
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(10),
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 8),
        decoration: BoxDecoration(
          color: color.withOpacity(0.12),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: color.withOpacity(0.35)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(icon, size: 16, color: color),
            const SizedBox(height: 3),
            Text(
              label,
              style: TextStyle(
                fontFamily: 'Inter',
                fontSize: 10.5,
                fontWeight: FontWeight.w600,
                color: color,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _SectionBox extends StatelessWidget {
  final String title;
  final IconData icon;
  final String content;
  final bool isCode;

  const _SectionBox({
    required this.title,
    required this.icon,
    required this.content,
    this.isCode = false,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            Icon(icon, size: 14, color: const Color(0xFF5EA9FF)),
            const SizedBox(width: 6),
            Text(
              title,
              style: const TextStyle(
                fontFamily: 'Inter',
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: Color(0xFF5EA9FF),
                letterSpacing: 0.2,
              ),
            ),
          ],
        ),
        const SizedBox(height: 6),
        Container(
          width: double.infinity,
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: const Color(0xFF08192D).withOpacity(0.70),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(color: const Color(0xFF1E3A5F)),
          ),
          child: Text(
            content,
            style: TextStyle(
              fontFamily: isCode ? 'monospace' : 'Inter',
              fontSize: isCode ? 11.5 : 12.5,
              height: 1.55,
              color: const Color(0xFFE2E8F0),
            ),
          ),
        ),
      ],
    );
  }
}

class _AiLoadingView extends StatelessWidget {
  const _AiLoadingView();

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const SizedBox(height: 12),
        const Row(
          children: [
            SizedBox(
              width: 16,
              height: 16,
              child: CircularProgressIndicator(
                strokeWidth: 2,
                color: Color(0xFF2DD4BF),
              ),
            ),
            SizedBox(width: 10),
            Text(
              'Gemini AI is analyzing topic and notes…',
              style: TextStyle(
                fontFamily: 'Inter',
                fontSize: 12,
                color: Color(0xFF2DD4BF),
              ),
            ),
          ],
        ),
        const SizedBox(height: 16),
        _shimmerBox(90),
        const SizedBox(height: 10),
        _shimmerBox(140),
        const SizedBox(height: 10),
        _shimmerBox(80),
      ],
    );
  }

  Widget _shimmerBox(double height) {
    return Container(
      height: height,
      decoration: BoxDecoration(
        color: const Color(0xFF1E3A5F).withOpacity(0.35),
        borderRadius: BorderRadius.circular(8),
      ),
    );
  }
}

class _AiErrorView extends StatelessWidget {
  final String error;
  final VoidCallback onRetry;

  const _AiErrorView({required this.error, required this.onRetry});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        const Icon(Icons.error_outline_rounded, color: AppColors.error, size: 30),
        const SizedBox(height: 8),
        const Text(
          'Could not generate explanation',
          style: TextStyle(
            fontFamily: 'Inter',
            fontSize: 13,
            fontWeight: FontWeight.w600,
            color: Colors.white,
          ),
        ),
        const SizedBox(height: 8),
        ElevatedButton.icon(
          onPressed: onRetry,
          icon: const Icon(Icons.refresh_rounded, size: 16),
          label: const Text('Retry'),
          style: ElevatedButton.styleFrom(
            backgroundColor: const Color(0xFF2563EB),
            foregroundColor: Colors.white,
          ),
        ),
      ],
    );
  }
}
